const fs = require('fs');
const key = JSON.parse(fs.readFileSync('C:/Users/Administrator/.easyclaw/workspace/n8n-lesson-crew/state/deepseek-key.json', 'utf-8')).apiKey;
async function ds(system, user, schemaHint) {
  const res = await this.helpers.httpRequest({
    method: 'POST',
    url: 'https://api.deepseek.com/chat/completions',
    headers: { 'Authorization': 'Bearer ' + key, 'Content-Type': 'application/json' },
    body: {
      model: 'deepseek-chat',
      messages: [
        { role: 'system', content: system + '\nYou MUST respond with a single valid JSON object matching this schema: ' + schemaHint + ' . No markdown fences, no extra text.' },
        { role: 'user', content: user }
      ],
      response_format: { type: 'json_object' },
      temperature: 0.7
    },
    json: true, timeout: 120000
  });
  const txt = res.choices[0].message.content;
  return JSON.parse(txt);  // 契约层: 与模板解析器一样无 try 兜底,崩了就是坑实锤
}

const out = await ds.call(this,
  'You are a helpful image generation prompt generator. Your task is to see what user wants and then generate a detailed image generation prompt.',
  $json.input, '{"prompt": "string"}');
if (!out.prompt) throw new Error('Agent1 missing prompt key');
return [{ json: { output: { prompt: out.prompt } } }];

