const dir = 'C:/Users/Administrator/.easyclaw/workspace/n8n-lesson-crew/state/19932-c-data';
const ts = Date.now();
const promptFile = dir + '/prompt-' + ts + '.txt';
const imgFile = dir + '/post-' + ts + '.png';
fs.writeFileSync(promptFile, prompt, 'utf-8');
execFileSync('python', [
  'C:/Users/Administrator/.easyclaw/bundled-skill-overrides/image-gen/image-gen/scripts/generate_image.py',
  '--prompt-file', promptFile, '--filename', imgFile, '--size', size
], { stdio: ['ignore', 'pipe', 'pipe'], timeout: 300000 });
const st = fs.statSync(imgFile);
return [{ json: { imagePath: imgFile, imageBytes: st.size, usedPrompt: prompt, usedSize: size } }];

