// 模板 text 表达式原文:
const inputText = 'Instagram Post : ' + $json.output.instagram
  + '\nLinkedIn Post : ' + $json.output.linkedin
  + '\nTwitter (X) Post: ' + $json.output['twitter (x)']
  + '\n\nImage Link : ' + $('C Local Host').item.json.webViewLink;
const out = await ds.call(this,
