const fs = require('fs');
const results = [];
function T(name, fn) {
  try { const r = fn(); results.push({ name, ok: r === true, actual: r === true ? undefined : r }); }
  catch (e) { results.push({ name, ok: false, actual: 'THROW: ' + e.message }); }
}
const rendered = $json.output['html file code'];
const scene = $('Scene Input').item.json;
const p = $('C Prompt Agent (DeepSeek)').item.json.output.prompt;
const img = $('C Seedream Image').item.json;
const host = $('C Local Host').item.json;
const social = $('C Post Content Agent (DeepSeek)').item.json.output;
const agentInput = $json.agentInputText;

T('C1 DeepSeek Agent1 真调出 prompt（非空且围绕创意）', () => p.length > 10 ? true : p);
T('C2 prompt 与场景 input 语义相关（含 honey 或概念词）',
  () => /honey|jar|wooden|farmhouse/i.test(p) ? true : p);
T('C3 Seedream 真生图: 文件存在且 >50KB', () => img.imageBytes > 50 * 1024 ? true : img.imageBytes);
T('C4 尺寸映射: 竖版 1024x1536 透传', () => img.usedSize === '1024x1536' ? true : img.usedSize);
T('C5 本地托管链接替代 Drive（无 403 风险）', () => host.webViewLink.startsWith('file:///') ? true : host.webViewLink);
T('C6 DeepSeek Agent2 三平台文案全非空',
  () => social.instagram.length > 5 && social.linkedin.length > 5 && social['twitter (x)'].length > 5 ? true : social);
T('C7 "twitter (x)" 键真跑取值成功', () => typeof social['twitter (x)'] === 'string' ? true : 'missing');
T('C8 HTML Agent 输入串四要素齐全（模板表达式忠实复现）',
  () => agentInput.includes('Instagram Post :') && agentInput.includes('Twitter (X) Post:')
     && agentInput.includes(host.webViewLink) ? true : agentInput);
T('C9 DeepSeek Agent3 产出 HTML', () => rendered.length > 100 && rendered.toLowerCase().includes('<') ? true : rendered);
T('C10 HTML 含 check image 按钮（systemMessage 契约）', () => /check image/i.test(rendered) ? true : rendered.slice(0, 200));
T('C11 HTML 引用图片链接', () => rendered.includes(host.webViewLink) || rendered.includes('post-') ? true : rendered.slice(0, 200));
T('C12 三平台文案进 HTML', () => rendered.includes(social.instagram.slice(0, 20)) ? true : rendered.slice(0, 200));

// 落盘最终 HTML 供人工/浏览器验收
const outHtml = 'C:/Users/Administrator/.easyclaw/workspace/n8n-lesson-crew/state/19932-c-data/final-result.html';
fs.writeFileSync(outHtml, rendered, 'utf-8');

const failed = results.filter(x => !x.ok);
return [{ json: { total: results.length, passed: results.length - failed.length, failed: failed.length,
                  failures: failed.map(f => ({ name: f.name, actual: String(f.actual).slice(0, 300) })),
                  artifacts: { html: outHtml, image: img.imagePath, imageBytes: img.imageBytes },
                  sample: { prompt: p, instagram: social.instagram.slice(0, 80) } } }];
